window.products.push({"id":1167233,"name":"SkyTech 3301P Programmable Fireplace Remote Control (SKY-3301P)","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/5137RToi40L._AC_SL1500_.jpg","description":"The Skytech 3301 P remote control system was developed to provide a safe, reliable, and user-friendly remote control system for gas heating appliance. The system can be operated thermostatically or manually from the transmitter. This fireplace remote control is easily programmed to your custom settings. The system operates on radio frequencies (RF) within a 20' range using non-directional signals. The system operates one of 1,048,576 security codes that are programmed into the transmitter at the factory; the remote receiver's code must be matched to that of the transmitter prior to initial use.","images":["https://m.media-amazon.com/images/I/5137RToi40L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"SkyTech","source_asin":"B000FS3IGK","category_path":"Home & Kitchen"},"sku":"BM-1167233","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B000FS3IGK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B000FS3IGK","price_pending":true,"merchant_ready":false});
